#include<stdio.h>
#define max(p,q)((p)>(q)?(p):(q))

int n,m;
int e[11][11];
int used[11];
int ans;
void dfs(int v,int sum){
	used[v]=1;
	ans=max(ans,sum);
	for(int i=1;i<=n;i++)if(!used[i]&&e[v][i])dfs(i,sum+e[v][i]);
	used[v]=0;
}

int main(){
	scanf("%d%d",&n,&m);
	for(int i=0;i<m;i++){
		int a,b,c;
		scanf("%d%d%d",&a,&b,&c);
		e[a][b]=e[b][a]=c;
	}
	for(int i=1;i<=n;i++)dfs(i,0);
	printf("%d\n",ans);
}
